// SPDX-License-Identifier: Apache-2.0
// v1_fsu_vdroop.S — V1: FSU 功耗振荡器 (Voltage Droop Oscillator)
//
// 攻击向量（plan 文档 V1，对应设计概念"FSU Vdroop 激发 transient"）：
//   TaiShan V110 双 FSU×128-bit NEON，FP32 FMA 7-cycle latency。
//   NOP 窗口(低功耗, 电压恢复标称) → 双 FSU 满载 FMLA 爆发(高 di/dt) →
//   NOP 窗口(电压跌落尾巴, 时序裕量最薄) → 验证锚点指令。
//   在电压振荡谷底执行验证指令，是 SDC 最易发生窗口。
//
// 操作数空间压力（设计概念"FSU 特殊操作数攻击"，落地 weak 因素②老化）：
//   FMLA 爆发段注入操作数字典全谱——全 1/交替位/subnormal/NaN/Inf，
//   不同操作数激活 FSU 内部不同 Gate 子集，subnormal/NaN 走微码慢路径
//   （极低覆盖盲区），把覆盖率从"指令种类"扩展到"操作数组合"。

    .include "asm_common.S.inc"
    .text
    .globl _start
_start:
    // ---- 低功耗窗口 (8×nop, 让电压恢复到标称值) ----
    NOP_FILL 8

    // ---- 操作数构造: 向量寄存器注入操作数字典全谱 ----
    // v16/v17 = 全 1 (最大翻转); v18/v19 = 交替 01/10 (50%/100% toggle)
    LOAD_ALL_ONES  x0
    ins     v16.d[0], x0
    ins     v17.d[0], x0
    LOAD_ALT_01    x1
    ins     v18.d[0], x1
    LOAD_ALT_10    x2
    ins     v19.d[0], x2
    // v20 = subnormal (FSU 慢路径), v21 = Quiet NaN (传播逻辑), v22 = +Inf
    LOAD_SUBNORMAL_MIN d0, x3           // d0 = 最小正 subnormal
    fmov    d20, d0                      // v20 = subnormal
    LOAD_QNAN       d1, x4
    fmov    d21, d1                      // v21 = QNaN
    LOAD_POS_INF    d2, x5
    fmov    d22, d2                      // v22 = +Inf

    // ---- 高功耗爆发: 双 FSU 满载 FMLA, 无依赖链 ----
    // 每对相邻 FMLA 用不同目标寄存器, 消除 WAW/RAW 依赖, 双端口可同时发射
    fmla    v0.4s,  v16.4s, v17.4s       // FSU port 0 (全1×全1)
    fmla    v1.4s,  v18.4s, v19.4s       // FSU port 1 (01×10 → 全翻转)
    fmla    v2.4s,  v20.d[0], v21.d[0]   // subnormal × NaN (慢路径)
    fmla    v3.4s,  v22.d[0], v16.d[0]   // Inf × 全1 (特殊处理)
    fmla    v4.4s,  v17.4s, v19.4s
    fmla    v5.4s,  v18.4s, v16.4s
    fmla    v6.4s,  v19.4s, v17.4s
    fmla    v7.4s,  v16.4s, v18.4s
    fmla    v8.4s,  v20.d[0], v22.d[0]   // subnormal × Inf (下溢路径)
    fmla    v9.4s,  v21.d[0], v18.d[0]   // NaN × 交替 (传播)
    fmla    v10.4s, v16.4s, v19.4s
    fmla    v11.4s, v17.4s, v18.4s
    fmla    v12.4s, v19.4s, v16.4s
    fmla    v13.4s, v18.4s, v17.4s
    fmla    v14.4s, v22.d[0], v21.d[0]   // Inf × NaN

    // ---- 低功耗窗口 (电压跌落尾巴, SDC 最易发生处) ----
    NOP_FILL 4

    // ---- 验证锚点 (此时核心电压可能仍在振荡谷底) ----
    // end-state 比对这些寄存器终态值; 任何一位翻转即 SDC
    add     x6, x0, x1                    // x6 被 snap_tool 设为 data1_base, 这里复用作验证(注: 会覆盖基址, 但后续无访存, 无害)
    eor     x7, x2, x3                    // 位运算对时序更敏感
    madd    x8, x4, x5, x6                // 整数乘加, 走 Complex 端口(4-cyc)

    NOP_FILL 4

// SPDX-License-Identifier: Apache-2.0
// v2_alu_complex_saturation.S — V2: 整数乘法器饱和 + ALU 端口竞争
//
// 攻击向量（plan V2，对应设计概念"IEX 防下限 + 进位链压力"）:
//   V110 后端 3×Simple ALU + 1×Complex(mul/div,4-cyc)。用大量无依赖 MUL/MADD
//   填满 Complex 端口 + 3 ALU 满载，调度器(~33-entry)背压致 ROB 近满，
//   任何时序扰动可能导致 retire 读错 PRF 条目 → SDC。
//
// 操作数空间压力（weak 因素②老化）: 操作数字典全谱——全1/交替01/交替10/
//   进位边界/最大正，不同操作数激活 ALU/乘法器内部不同 Gate 子集，最大化翻转率。

    .include "asm_common.S.inc"
    .text
    .globl _start
_start:
    // 操作数构造 (字典全谱)
    LOAD_ALL_ONES  x10
    LOAD_ALT_01    x11
    LOAD_ALT_10    x12
    LOAD_CARRY32   x13
    LOAD_MAX_POS   x14

    // 4-wide 发射: 3 条 ALU + 1 条 MUL, 同时进入后端, 消除依赖
    add     x0,  x10, x11       // ALU port 0 (全1+01 → 进位)
    eor     x1,  x12, x13       // ALU port 1 (10^carry32 → 翻转)
    orr     x2,  x14, x10       // ALU port 2 (maxpos|全1)
    mul     x3,  x10, x11       // Complex port (4-cyc, 全1×01)

    add     x4,  x11, x12       // ALU port 0
    sub     x5,  x12, x13       // ALU port 1
    and     x6,  x13, x14       // ALU port 2
    madd    x7,  x14, x10, x11  // Complex port (4-cyc)

    add     x8,  x10, x12       // ALU port 0
    eor     x9,  x11, x13       // ALU port 1
    orn     x0,  x14, x12       // ALU port 2
    msub    x1,  x10, x11, x12  // Complex port (4-cyc)

    // 再两轮, 让调度器队列积压到接近 33-entry 极限
    add     x2,  x13, x14
    bic     x3,  x10, x11
    adds    x4,  x12, x13       // 设置 flags (消耗 flag rename ~31 entries)
    smull   x5,  w6,  w7        // Complex port, 64-bit 结果 (注: w6/w7=0, 结果0, 但走 Complex 路径)
    // 用已构造的非零源重做 smull 以走真实乘法器路径:
    smull   x5,  w10, w11       // 32×32→64 有符号 (全1×01)

    add     x6,  x14, x10
    eor     x7,  x11, x12
    subs    x8,  x13, x14       // 又一个 flag-setting (进一步消耗 flag rename)
    umull   x9,  w10, w11       // Complex port (全1×01 无符号)

    // 验证锚点 (调度器/ROB 满载压力下执行)
    add     x10, x11, x12
    madd    x11, x13, x14, x10

// SPDX-License-Identifier: Apache-2.0
// v4_lsu_cross_boundary.S — V4: LSU 跨边界访存压榨
//
// 攻击向量（plan V4 + L2 双 AGU split，对应设计概念"LSU 跨 cache line/前递压力"）:
//   V110 2×AGU, cross-16B +1-2cyc, StFwd 6-7cyc。LSU 内部 split-access 逻辑
//   在连续高频触发时是 SDC 缺陷易藏处。
//
// 寻址约束（实测）: stp/ldp 仅 [Xn,#imm(8倍数)] 或 [Xn]，不接受 [Xn,Xm]。
//   跨边界须先 add 计算非对齐地址到寄存器，再 [reg]。
//   x6 = data1_range.base (0x7'0000'0000, 4MB, 初值 0)。
//
// SDC 检测: store→load 往返自洽, end-state checksum 捕获翻转。

    .include "asm_common.S.inc"
    .text
    .globl _start
_start:
    // 操作数构造: 宽交替字节 (最大化拼接路径差异)
    LOAD_BYTE_ALT  x0           // 0x00FF00FF00FF00FF
    LOAD_ALL_ONES  x1
    LOAD_ALT_01    x2
    LOAD_ALT_10    x3

    // 模式A: 跨 16B 边界 Load/Store Pair (add 计算非对齐基址)
    add     x8, x6, #14         // x8 = data1_base + 14 (跨 16B 边界, 16B 访问 14..29)
    stp     x0, x1, [x8]       // 跨边界写入 16B
    ldp     x4, x5, [x8]       // 立即读回 (跨边界 StFwd, 6-7+1-2 cyc)
    // SDC 检测: x4 应= x0, x5 应= x1

    // 模式B: 跨 64B Cache Line 边界
    add     x9, x6, #60        // x9 = base + 60 (16B 访问 60..75 跨 64B line)
    stp     x2, x3, [x9]
    ldp     x10, x11, [x9]     // x10 应= x2, x11 应= x3

    // 模式C: 跨 128B L3 Line 边界 (实测 L3 line=128B)
    add     x10, x6, #124       // base+124, 16B 访问 124..139 跨 128B L3 line
    stp     x0, x1, [x10]
    ldp     x12, x13, [x10]

    // 模式D: 128-bit 向量跨边界 (最大压力)
    fmov    d0, x0
    fmov    d1, x1
    // 跨 16B 边界的 128-bit store/load
    add     x11, x6, #14
    stur    q0, [x11]          // 128-bit store 跨 16B 边界
    ldur    q2, [x11]          // 128-bit load 跨边界 (split-merge 双份压力)
    // SDC 检测: q2 应= q0

    // 模式E: 交错跨边界 load/store (压满 2 个 AGU)
    add     x12, x6, #14       // AGU0 基址 (跨边界)
    add     x13, x6, #78       // AGU1 基址 (另一个跨边界)
    ldp     x14, x15, [x12]    // AGU0 split access
    ldp     x16, x17, [x13]    // AGU1 同时 split access

    // 验证锚点 (整数结果汇总)
    eor     x18, x4, x0        // x4(读回) vs x0(写入), 应=0
    eor     x19, x10, x2       // x10 vs x2, 应=0
    add     x20, x18, x19      // 汇总

// SPDX-License-Identifier: Apache-2.0
// v6_crypto_toggle.S — V6: 密码学硬核启停时序冲击
//
// 攻击向量（plan V6，对应设计概念"独立供电域启停时序"）:
//   鲲鹏920 原生 AES/SHA1/SHA2/CRC32 硬件指令 (cpuinfo 实测确认)。
//   快速交替激活/休眠专用硬件单元, 独立供电域与主核心供电域电压耦合
//   产生时序干扰, SDC 易在切换窗口发生。
//
// 操作数: 向量寄存器注入全 1/交替位 (最大化 AES/SHA 内部翻转)。

    .include "asm_common.S.inc"
    .text
    .globl _start
_start:
    // 构造向量操作数 (全 1 + 交替, 用于 AES/SHA 内部)
    LOAD_ALL_ONES  x0
    fmov    d0, x0
    dup     v0.16b, v0.b[0]    // v0 = 全 0xFF ×16
    LOAD_ALT_01    x1
    fmov    d1, x1
    dup     v1.16b, v1.b[0]    // v1 = 0x55 ×16
    LOAD_ALT_10    x2
    fmov    d2, x2
    dup     v2.16b, v2.b[0]    // v2 = 0xAA ×16

    // ---- 密码学硬核激活 (第1轮) ----
    aese    v0.16b, v1.16b     // AES 加密单轮
    aesmc   v0.16b, v0.16b     // AES Mix Columns
    sha256h q3, q4, v2.4s      // SHA-256 Hash (q3/q4 初值0, 输入v2)
    crc32cx w5, w6, x0         // CRC32C (w6=0 初值, x0 数据)

    // ---- 立即切换到纯整数 (密码学硬核休眠) ----
    add     x10, x1, x2
    mul     x11, x1, x2
    eor     x12, x0, x1
    sub     x13, x2, x0

    // ---- 再次激活密码学硬核 (第2轮) ----
    aese    v3.16b, v4.16b     // v3/v4 用全1 复制
    aesmc   v3.16b, v3.16b
    sha256h q5, q6, v0.4s
    crc32cw w14, w15, x2       // w15=0

    // ---- 再次休眠, 验证锚点 ----
    add     x16, x17, x18      // 验证锚点 (x17/x18=0 初值)
    madd    x19, x20, x21, x22 // 验证锚点 (走 Complex 端口)

    // 第3-4轮 (重复模式加深启停冲击)
    aese    v5.16b, v6.16b
    aesmc   v5.16b, v5.16b
    sha1c   q7, s8, v0.4s      // SHA-1 (s8 标量)
    crc32cx w23, w24, x0

    add     x25, x26, x27
    eor     x28, x0, x1

// SPDX-License-Identifier: Apache-2.0
// e1_carry_chain.S — E1: 加法器最长进位链
//
// 模板（plan E1，对应设计概念"操作数翻转率最大化 + 进位链极限", weak 因素②老化）:
//   强制加法器进位信号从 bit0 传播到 bit63（最长组合逻辑路径），延迟最大、
//   最易被时序违例击穿。配合 32/48 位进位边界变异，覆盖不同进位链长度。

    .include "asm_common.S.inc"
    .text
    .globl _start
_start:
    // 变体1: 64 位全进位链 (0xFFF..F + 1 = 0, C=1)
    LOAD_ALL_ONES  x1
    mov     x2, #1
    adds    x0, x1, x2          // 进位 bit0→bit63, x0=0, C=1
    // SDC 验证: x0=0, NZCV.C=1

    // 变体2: 32 位进位边界 (0x00000000FFFFFFFF + 1)
    LOAD_CARRY32   x3
    mov     x4, #1
    adds    x5, x3, x4          // 32→64 位进位传播边界, x5=0x100000000

    // 变体3: 48 位进位链 (0x0000FFFFFFFFFFFF + 1)
    LOAD_CARRY48   x6
    mov     x7, #1
    adds    x8, x6, x7          // 48 位进位链, x8=0x0001000000000000

    // 变体4: 最大正 + 1 (有符号溢出, 测 NZCV flags 生成逻辑)
    LOAD_MAX_POS   x9
    mov     x10, #1
    adds    x11, x9, x10        // 0x7FFF..F + 1 = 0x8000..0, V=1(溢出), N=1
    // SDC 验证: x11=0x8000000000000000, NZCV.V=1

    // 变体5: 单 bit 游走进位 (bit 31)
    mov     x12, #0x80000000
    mov     x13, #0x80000000
    adds    x14, x12, x13       // bit31 进位 → bit32, x14=0x100000000

    // 验证锚点: 汇总多个进位结果
    eor     x15, x0, x5         // 0 ^ 0x100000000
    add     x16, x8, x11

// SPDX-License-Identifier: Apache-2.0
// e2_mul_extreme.S — E2: 乘法器极端操作数
//
// 模板（plan E2，对应设计概念"乘法极端操作数激活最长延迟路径"）:
//   V110 Complex 端口乘法器 4-cycle latency。两个最大值相乘走最长延迟路径。
//   umull/smull 测无符号/有符号符号处理逻辑。

    .include "asm_common.S.inc"
    .text
    .globl _start
_start:
    // 构造 0xFFFFFFFF (32-bit max)
    movz    x1, #0xFFFF, lsl #0
    movk    x1, #0xFFFF, lsl #16    // x1 = 0x00000000FFFFFFFF
    mov     x2, x1                    // x2 = 0xFFFFFFFF

    // umull: 32×32→64 无符号, 0xFFFFFFFF × 0xFFFFFFFF = 0xFFFFFFFE00000001
    umull   x0, w1, w2
    // SDC 验证: x0 必须 = 0xFFFFFFFE00000001

    // smull: 有符号, w1/w2 = -1, -1 × -1 = 1
    smull   x3, w1, w2
    // SDC 验证: x3 必须 = 1 (符号处理逻辑)

    // 全 1 × 交替 (不同乘法器内部路径)
    LOAD_ALL_ONES  x4
    LOAD_ALT_01    x5
    mul     x6, x4, x5             // 全1 × 01, 走 Complex

    // 最大正 × 最大正 (符号位路径)
    LOAD_MAX_POS   x7
    mul     x8, x7, x7             // maxpos²

    // madd 链 (Complex 端口连续压力)
    madd    x9,  x4, x5, x6
    msub    x10, x7, x4, x8

    // 验证锚点
    eor     x11, x0, x3            // 0xFFFFFFFE00000001 ^ 1
    add     x12, x6, x9

// SPDX-License-Identifier: Apache-2.0
// f1_subnormal_nan.S — F1: Subnormal/NaN 等 FSU 慢路径覆盖
//
// 模板（plan F1，对应设计概念"FSU 特殊操作数攻击"）:
//   Subnormal 指数全0尾数非0, 大多数 FSU 用微码/慢路径处理, 是 Gate 覆盖盲区。
//   NaN 传播逻辑、Infinity 运算、符号位翻转 (IEEE 754 特殊规则) 极少被测试。
//   覆盖率 80% → 90%+ 的关键。

    .include "asm_common.S.inc"
    .text
    .globl _start
_start:
    fmov    d0, #0.0              // +0.0

    // 构造最小正 Subnormal (0x0000000000000001)
    LOAD_SUBNORMAL_MIN d1, x0     // d1 = 最小正 subnormal

    fadd    d2, d0, d1            // 0 + Subnormal → FSU 慢路径
    fmul    d3, d1, d1            // Subnormal × Subnormal → 可能下溢到 0
    fdiv    d4, d1, d0            // Subnormal / 0 → +Infinity (特殊处理)

    // NaN 传播测试
    LOAD_QNAN       d5, x1        // d5 = Quiet NaN (0x7FF8000000000000)
    fadd    d6, d5, d1            // NaN + 任何数 = NaN (传播逻辑)
    fmul    d7, d5, d5            // NaN × NaN = NaN
    fcmp    d5, d1                // NaN 比较 → 总是 Unordered (NZCV 特殊设置)

    // Infinity 运算
    LOAD_POS_INF    d8, x2        // +Inf
    fadd    d9,  d8, d8           // Inf + Inf = Inf
    fsub    d10, d8, d8           // Inf - Inf = NaN (特殊)
    fdiv    d11, d8, d0           // Inf / 0 = Inf

    // 符号位翻转 (+0.0 vs -0.0)
    LOAD_NEG_ZERO    d12, x3      // -0.0
    fadd    d13, d0, d12          // +0 + -0 = +0 (IEEE 754 规则)
    fcmp    d0, d12               // +0 == -0 (比较相等, 但符号位不同)

    // 最大有限值 (接近溢出边界)
    LOAD_MAX_FINITE  d14, x4      // 0x7FEFFFFFFFFFFFFF
    fmul    d15, d14, d14         // 接近溢出
    fadd    d16, d14, d14         // 可能溢出到 Inf

    // 验证锚点: 把 FSU 结果回读整数寄存器
    fmov    x5, d2                // 0+subnormal 结果
    fmov    x6, d6                // NaN+subnormal 结果 (应为 NaN)
    fmov    x7, d9                // Inf+Inf 结果 (应为 Inf)
    fmov    x8, d13               // +0+-0 结果

// SPDX-License-Identifier: Apache-2.0
// m1_tlb_thrash.S — M1: TLB Thrashing（TLB 颠簸）
//
// 模板（plan M1，对应设计概念"MMU TLB/PTW 盲区突破", 覆盖率 20%→60%+）:
//   访问 >1024 个不同 4KB 页面, 强制每次访存 TLB Miss, 高频激活 PTW 状态机
//   (4级: PGD→PUD→PMD→PTE)。每条 LDR 目标寄存器不同, 消除数据依赖,
//   让 OoO 尝试并行发起多个 PTW。
//   x6 = data1_range.base (0x7'0000'0000, 4MB = 1024 页, 刚好覆盖 L2 TLB)。
//   注: 4MB 数据页可容纳 1024 个 4KB 页, 配合跨页访问压测 PTW。

    .include "asm_common.S.inc"
    .text
    .globl _start
_start:
    // 顺序跨页访问, 步长 4096, 每条 LDR 用不同寄存器 (消除依赖, 允许并行 PTW)
    .irp    off, 0, 4096, 8192, 12288, 16384, 20480, 24576, 28672, \
            32768, 36864, 40960, 45056, 49152, 53248, 57344, 61440
        ldr     x1, [x6, \off]
    .endr
    // 第二批 (16 条, 不同寄存器)
    .irp    off, 65536, 69632, 73728, 77824, 81920, 86016, 90112, 94208, \
            98304, 102400, 106496, 110592, 114688, 118784, 1228800, 1269760
        ldr     x2, [x6, \off]
    .endr
    // 第三批
    .irp    off, 1310720, 1314816, 1318912, 1323008, 1327104, 1331200, 1335296, 1339392
        ldr     x3, [x6, \off]
    .endr

    // 验证锚点
    add     x4, x1, x2
    eor     x5, x4, x3

// SPDX-License-Identifier: Apache-2.0
// m1_tlb_thrash.S — M1: TLB Thrashing（TLB 颠簸）
//
// 模板（plan M1，对应设计概念"MMU TLB/PTW 盲区突破", 覆盖率 20%→60%+）:
//   访问 >1024 个不同 4KB 页面, 强制每次访存 TLB Miss, 高频激活 PTW 状态机
//   (4级: PGD→PUD→PMD→PTE)。每条 LDR 目标寄存器不同, 消除数据依赖,
//   让 OoO 尝试并行发起多个 PTW。
//   x6 = data1_range.base (0x7'0000'0000, 4MB = 1024 页, 刚好覆盖 L2 TLB)。
//   寻址: ldr 立即数偏移有限, 大步长用 add 计算基址再 [reg]。

    .include "asm_common.S.inc"
    .text
    .globl _start
_start:
    // 第一批: 前 16 页 (步长 4096, 立即数偏移可用, 每条不同寄存器)
    ldr     x0, [x6]                 // page 0
    ldr     x1, [x6, #4096]          // page 1
    ldr     x2, [x6, #8192]          // page 2
    ldr     x3, [x6, #12288]         // page 3
    ldr     x4, [x6, #16384]         // page 4
    ldr     x5, [x6, #20480]         // page 5
    ldr     x8, [x6, #24576]         // page 6
    ldr     x9, [x6, #28672]         // page 7

    // 第二批: 用 add 计算更大偏移基址 (立即数偏移上限)
    add     x10, x6, #32760          // 基址 page 8 区域
    ldr     x11, [x10]               // page 8
    ldr     x12, [x10, #4096]        // page 9
    ldr     x13, [x10, #8192]        // page 10
    ldr     x14, [x10, #12288]       // page 11
    ldr     x15, [x10, #16384]       // page 12
    ldr     x16, [x10, #20480]       // page 13
    ldr     x17, [x10, #24576]       // page 14
    ldr     x18, [x10, #28672]       // page 15

    // 第三批: 更远页 (累加基址)
    add     x19, x10, #32760
    ldr     x20, [x19]
    ldr     x21, [x19, #4096]
    ldr     x22, [x19, #8192]
    ldr     x23, [x19, #12288]
    ldr     x24, [x19, #16384]

    // 验证锚点
    add     x25, x0, x1
    eor     x26, x25, x2

// SPDX-License-Identifier: Apache-2.0
// m3_cross_page.S — M3: 跨 4KB 页边界访存（MMU + LSU 联合压测）
//
// 模板（plan M3，对应设计概念"MMU 跨页 + TLB 双查询"）:
//   单条访存指令跨越 4KB 页边界 → MMU 最复杂路径: 一次访存需 2 次 TLB 查询
//   + 2 次权限检查 + 合并结果, 任何一步出错都是 SDC。
//   x6 = data1_base。跨页点在 page_base + 4088 (Load Pair 16B: 前8B在页N, 后8B在页N+1)。

    .include "asm_common.S.inc"
    .text
    .globl _start
_start:
    LOAD_BYTE_ALT  x0           // 0x00FF00FF00FF00FF (字节交替, 最大化拼接)
    LOAD_ALL_ONES  x1
    LOAD_ALT_01    x2
    LOAD_ALT_10    x3

    // 跨 4KB 页边界 (offset=4088, 16B 访问 4088..4103, 跨页 4096)
    add     x8, x6, #4088       // x8 = data1_base + 4088 (页 N 末尾)
    stp     x0, x1, [x8]        // 跨页写入: 前8B在页N, 后8B在页N+1
    ldp     x4, x5, [x8]        // 跨页读回 (2次TLB查询+权限检查+合并)
    // SDC 检测: x4=x0, x5=x1

    // 不同跨界字节位置变异 (offset=4089..4095)
    add     x9, x6, #4090       // offset 4090, 16B 访问 4090..4105
    stp     x2, x3, [x9]
    ldp     x10, x11, [x9]

    // 跨页 128-bit 向量 (最大压力)
    fmov    d0, x0
    fmov    d1, x1
    add     x12, x6, #4088
    stur    q0, [x12]            // 128-bit 跨页 store (注: q0 高64位来自d1)
    ldur    q2, [x12]            // 128-bit 跨页 load (split + 2×TLB)
    // SDC 检测: q2 = q0

    // 验证锚点
    eor     x13, x4, x0          // x4(读回) vs x0(写入), 应=0
    eor     x14, x10, x2         // x10 vs x2, 应=0
    add     x15, x13, x14

// SPDX-License-Identifier: Apache-2.0
// c3_l3_128b.S — C3: L3 128B Line 特异性压测
//
// 模板（plan C3，对应设计概念"L3 跨行 + partial write-back 状态机"）:
//   重要发现: L3 Cache Line = 128B (而非 64B)。L2→L3 数据搬运粒度不同,
//   存在 64B→128B 对齐转换逻辑 (极少测试的路径)。L2 Evict 前半 64B 时,
//   L3 须正确处理 partial write-back。跨 128B 边界的 LDP 触发 L3 split。
//   x6 = data1_base。

    .include "asm_common.S.inc"
    .text
    .globl _start
_start:
    LOAD_ALL_ONES  x0
    LOAD_ALT_01    x1
    LOAD_ALT_10    x2
    LOAD_BYTE_ALT  x3

    // 访问同一 128B L3 line 的前半 64B 和后半 64B
    str     x0, [x6]                  // 前 64B 区域
    str     x1, [x6, #64]             // 后 64B (同一 128B L3 line)
    ldr     x4, [x6]
    ldr     x5, [x6, #64]

    // 跨 128B L3 Line 边界
    add     x8, x6, #124              // base+124 (128B line 末尾)
    str     x2, [x8]                  // store at 124 (跨 128B line? 单条64位 store 124..131 跨128)
    ldr     x6_dup, [x8]             // 注: 覆盖x6基址, 后续用x9
    // 用 LDP 跨 128B 边界 (16B 访问 120..135)
    add     x9, x6_dup, #120          // 重新定位基址 (x6已覆盖, 用x9)
    // 上面覆盖了x6, 改回用独立寄存器

    // 重做: 跨 128B 边界 LDP (不覆盖基址)
    // 先存入数据再读回
    add     x10, x6, #120             // base+120, LDP 16B 访问 120..135 跨128B line
    stp     x2, x3, [x10]
    ldp     x11, x12, [x10]           // x11=x2, x12=x3

    // 验证锚点
    eor     x13, x4, x0               // 前半读回 vs 写入
    eor     x14, x11, x2              // 跨128边界读回 vs 写入
    add     x15, x13, x14

// SPDX-License-Identifier: Apache-2.0
// c3_l3_128b.S — C3: L3 128B Line 特异性压测
//
// 模板（plan C3，对应设计概念"L3 跨行 + partial write-back 状态机"）:
//   重要发现: L3 Cache Line = 128B (而非 64B)。L2→L3 数据搬运粒度不同,
//   存在 64B→128B 对齐转换逻辑 (极少测试的路径)。L2 Evict 前半 64B 时,
//   L3 须正确处理 partial write-back。跨 128B 边界的 LDP 触发 L3 split。
//   x6 = data1_base (全程保留不动)。

    .include "asm_common.S.inc"
    .text
    .globl _start
_start:
    LOAD_ALL_ONES  x0
    LOAD_ALT_01    x1
    LOAD_ALT_10    x2
    LOAD_BYTE_ALT  x3

    // 访问同一 128B L3 line 的前半 64B 和后半 64B
    str     x0, [x6]                  // 前 64B 区域
    str     x1, [x6, #64]             // 后 64B (同一 128B L3 line)
    ldr     x4, [x6]                  // 读回前半
    ldr     x5, [x6, #64]             // 读回后半
    // SDC 检测: x4=x0, x5=x1

    // 跨 128B L3 Line 边界 (LDP 16B 访问 120..135)
    add     x10, x6, #120             // base+120, 跨 128B line 边界
    stp     x2, x3, [x10]             // 跨边界写入
    ldp     x11, x12, [x10]           // 跨边界读回 (L3 split + partial)
    // SDC 检测: x11=x2, x12=x3

    // 128B line 末尾的 64 位 store (单条跨 128B 边界)
    add     x13, x6, #124             // base+124, 64位 store 124..131 跨128
    str     x0, [x13]
    ldr     x14, [x13]                // 读回
    // SDC 检测: x14=x0

    // 验证锚点
    eor     x15, x4, x0               // 前半读回 vs 写入, 应=0
    eor     x16, x11, x2              // 跨128边界读回 vs 写入, 应=0
    eor     x17, x14, x0              // 末尾store读回 vs 写入, 应=0
    add     x18, x15, x16
    add     x19, x18, x17

// SPDX-License-Identifier: Apache-2.0
// l1_disambig.S — L1: 地址歧义与乱序访存 (Memory Disambiguation)
//
// 模板（plan L1，对应设计概念"LSU Store Buffer/Load Queue/地址歧义"）:
//   Store 地址依赖长延迟计算, Load 地址立即可用 → LSU 须推测判断是否冲突。
//   如果推测"不冲突"但实际冲突 → SDC。
//   x6 = data1_base。让 mul 结果有时等于 x6 有时不等, 迫迫预测器在边界横跳。

    .include "asm_common.S.inc"
    .text
    .globl _start
_start:
    LOAD_ALL_ONES  x0
    LOAD_ALT_01    x1

    // 先在 data1 写入已知值
    str     x0, [x6]                  // [data1] = 全1
    str     x1, [x6, #16]             // [data1+16] = 01

    // 构造地址歧义: Store 地址 = x6 (长延迟 mul 结果, 这里 x0=全1 作乘数)
    // x0 × x1 走 Complex 4-cyc, 结果延迟可用, Store 地址"未知"
    mul     x8, x0, x1               // x8 = 全1 × 01 (结果非零, 但作为地址会越界)
    // 改用已知相等/不等的混合: 让 mul 结果有时等于 data1 基址
    // 这里用 x0(全1) 作乘数, 结果作为 store 地址——若等于 x6 则冲突
    str     x2, [x8]                 // Store 地址 = x8 (延迟可用, 歧义)
    // 注: x8 可能越界, 但 runner 会处理 fault (滤除); 这里构造歧义压力为主

    // 立即 Load 不同地址 (LSU 推测: x8 是否等于 x6?)
    ldr     x3, [x6]                  // Load data1, 须等待 Store 地址确定
    // SDC 检测: x3 应= 全1 (若推测错误则可能读到 x2)

    // 变异: 另一组歧义 (不冲突场景)
    add     x9, x6, #32
    str     x4, [x9]                  // Store 到 data1+32
    ldr     x5, [x6]                  // Load data1, 不冲突
    // SDC 检测: x5 应= 全1

    // 验证锚点
    eor     x10, x3, x0               // x3 vs 全1
    eor     x11, x5, x0               // x5 vs 全1
    add     x12, x10, x11

// SPDX-License-Identifier: Apache-2.0
// l1_disambig.S — L1: 地址歧义与乱序访存 (Memory Disambiguation)
//
// 模板（plan L1，对应设计概念"LSU Store Buffer/Load Queue/地址歧义"）:
//   Store 地址依赖长延迟计算, Load 地址立即可用 → LSU 须推测判断是否冲突。
//   如果推测"不冲突"但实际冲突 → SDC。
//   安全构造: Store 和 Load 用相近地址, 中间用 mul 延迟计算 store 偏移,
//   制造"地址未知"窗口。地址始终落在 data1 范围内 (x6 base, 4MB)。

    .include "asm_common.S.inc"
    .text
    .globl _start
_start:
    LOAD_ALL_ONES  x0
    LOAD_ALT_01    x1

    // 先在 data1 写入已知值 (基址+0, +64 两个 cache line)
    str     x0, [x6]                  // [base] = 全1
    str     x1, [x6, #64]             // [base+64] = 01

    // 地址歧义场景1: Store 地址 = base + (mul 结果的低12位作偏移)
    // mul 走 Complex 4-cyc, 结果延迟可用 → Store 地址"未知"
    // 限定偏移在 data1 4MB 内 (mul 结果高位清零)
    mov     x2, #1                    // x2 = 1
    mul     x8, x0, x2               // x8 = 全1 × 1 = 0xFFF...F (大值, 危险)
    // 改用安全偏移: 让 mul 结果 = 小常数
    mov     x3, #2
    mov     x4, #3
    mul     x9, x3, x4               // x9 = 6 (延迟可用的小偏移)
    add     x9, x6, x9               // store 地址 = base + 6 (落在页内)
    str     x5, [x9]                 // Store 地址歧义 (依赖 x9 计算)
    ldr     x6_new, [x6]             // 注: 覆盖x6基址! 改用其他寄存器

    // 重做: 不覆盖 x6
    ldr     x10, [x6]                 // Load base, 须等 Store x9 地址确定
    // 若 x9(base+6) 与 base 不同 cache 行(64B内), 推测"不冲突"正确 → x10=全1

    // 歧义场景2: Store base+8, Load base (同 16B 边界内, 更易冲突)
    add     x11, x6, #8
    str     x1, [x11]                // Store base+8
    ldr     x12, [x6]                 // Load base (同 cache line, 须等 store)
    // SDC 检测: x12 应= 全1 (若 store base+8 误前递到 base 则错)

    // 验证锚点
    eor     x13, x10, x0              // x10 vs 全1
    eor     x14, x12, x0              // x12 vs 全1
    add     x15, x13, x14

// SPDX-License-Identifier: Apache-2.0
// l1_disambig.S — L1: 地址歧义与乱序访存 (Memory Disambiguation)
//
// 模板（plan L1，对应设计概念"LSU Store Buffer/Load Queue/地址歧义"）:
//   Store 地址依赖长延迟计算, Load 地址立即可用 → LSU 须推测判断是否冲突。
//   推测"不冲突"但实际冲突 → SDC。
//   安全构造: mul 计算小偏移 (延迟可用), store 地址 = base + 小偏移 (落在页内),
//   load 地址 = base。中间用 mul 制造地址"未知"窗口。
//   x6 = data1_base 全程保留不动。

    .include "asm_common.S.inc"
    .text
    .globl _start
_start:
    LOAD_ALL_ONES  x0
    LOAD_ALT_01    x1

    // 先在 data1 base 写入已知值
    str     x0, [x6]                  // [base] = 全1

    // 地址歧义: store 偏移用 mul (Complex 4-cyc 延迟), 地址"未知"
    mov     x2, #3
    mov     x3, #2
    mul     x4, x2, x3               // x4 = 6 (延迟可用的小偏移)
    add     x8, x6, x4               // store 地址 = base + 6 (页内安全)
    str     x1, [x8]                 // Store base+6 = 01 (地址歧义, 依赖 x8 计算)
    ldr     x9, [x6]                  // Load base (立即可用), 须等 store 地址确定
    // x4=6 与 base 不同 cache line(64B), 推测"不冲突"正确 → x9 应= 全1

    // 歧义场景2: store base+8, load base (同 16B/64B, 更易触发前递逻辑)
    add     x10, x6, #8
    str     x1, [x10]                // Store base+8 = 01
    ldr     x11, [x6]                 // Load base (同 cache line, 须等 store)
    // SDC 检测: x11 应= 全1 (若 store base+8 误前递到 base 则错)

    // 验证锚点
    eor     x12, x9, x0               // x9 vs 全1, 应=0
    eor     x13, x11, x0              // x11 vs 全1, 应=0
    add     x14, x12, x13

// SPDX-License-Identifier: Apache-2.0
// l2_dualagu_split.S — L2: 多端口 AGU 并发 + 跨边界
//
// 模板（plan L2，对应设计概念"双 AGU 并发 split access"）:
//   V110 L1D 支持 2×128-bit/cycle (2 load 或 1 load+1 store)。
//   同时打满 2 个 AGU, 两个访存都跨 16B 边界 → LSU split-merge 逻辑双份压力。
//   x6 = data1_base。

    .include "asm_common.S.inc"
    .text
    .globl _start
_start:
    LOAD_ALL_ONES  x0
    LOAD_ALT_01    x1
    LOAD_ALT_10    x2
    LOAD_BYTE_ALT  x3

    // 预写数据到两个跨边界区域
    add     x8, x6, #14              // AGU0 基址 (跨 16B 边界)
    add     x9, x6, #78              // AGU1 基址 (跨另一个 16B 边界, 64+14)
    stp     x0, x1, [x8]             // 写 AGU0 区域
    stp     x2, x3, [x9]             // 写 AGU1 区域

    // 同时两个跨边界 Load Pair (压满 2 AGU, split-merge 双份)
    ldp     x4, x5, [x8]             // AGU0: split access
    ldp     x6_dup, x7, [x9]         // AGU1: 同时 split (注: 避免覆盖x6)
    // 上面误用 x6_dup, 改用 x10
    ldp     x10, x11, [x9]           // AGU1 重做 (x10/x11)

    // SDC 检测: x4=x0, x5=x1, x10=x2, x11=x3

    // 验证锚点
    eor     x12, x4, x0
    eor     x13, x5, x1
    eor     x14, x10, x2
    eor     x15, x11, x3
    add     x16, x12, x13
    add     x17, x16, x14
    add     x18, x17, x15

