    eor     x10, x5, x0              // 读回 vs 原值 (x0=读到的0), 应=0
    eor     x11, x8, x1              // 应=0
    eor     x12, x9, x2              // 应=0
    add     x13, x10, x11
    add     x14, x13, x12

